; state.s -- generated by tools/fwtask/gen_blobs.py (phase 11.29): item 12 and Q124: what survives between firmware tasks (cmd 1 writes, cmd 2 reads)
; Written from doc/specs/usse_isa.md and the records E475/E476 (pclink, lapc), E480 (wdf with
; nothing outstanding), E512 (stad then ldad), E146/E155 (the event task, pa0 to pa2); it is run
; as an EDM task from the page the kernel maps at heap + 0x20000 (index 0x4000). Rules: r0 to r31
; only, no sa write except state.s, no emit, no lock, every store the same value from every lane.

@entry 0
        mov r22, pclink
        mov r23, #0x00000000
        mov r24, #0x00000000
        mov r25, #0x00000000
        mov r26, #0x00000000
        p0 mov r23, #0x00000001
        p1 mov r24, #0x00000001
        p2 mov r25, #0x00000001
        p3 mov r26, #0x00000001
        mov r27, r20
        mov r28, r21
        mov r29, i0
        mov r31, i1
        mov r1, #0xdeadbeef                 ; @patch res+0
        ldad.bypassl1 r2, [r1,+#1], drc0
        wdf drc0
        and.testtanz.chan0 !c0, p0, r2, r2
        p0 br @work
tail:
        mov r30, #0xdeadbeef                ; @patch cont0
        mov pclink, r30
        lapc
work:
        xor.testtaz.chan0 !c0, p1, r2, #1
        p1 br @c1
        xor.testtaz.chan0 !c0, p1, r2, #2
        p1 br @c2
        br @tail
c2:
        mov r9, #0xdeadbeef                ; @patch res+288
        stad [r9,+#0], r22
        stad [r9,+#1], r23
        stad [r9,+#2], r24
        stad [r9,+#3], r25
        mov r9, #0xdeadbeef                ; @patch res+304
        stad [r9,+#0], r26
        stad [r9,+#1], r27
        stad [r9,+#2], r28
        stad [r9,+#3], r29
        mov r12, sa64
        mov r13, sa100
        mov r14, sa127
        mov r15, sa20
        mov r16, sa24
        mov r17, r31
        mov r9, #0xdeadbeef                ; @patch res+320
        stad [r9,+#0], r12
        stad [r9,+#1], r13
        stad [r9,+#2], r14
        stad [r9,+#3], r15
        mov r9, #0xdeadbeef                ; @patch res+336
        stad [r9,+#0], r16
        stad [r9,+#1], r17
        br @done
c1:
        mov r12, #0xa5000040
        mov sa64, r12
        mov r12, #0xa5000064
        mov sa100, r12
        mov r12, #0xa500007f
        mov sa127, r12
        mov r12, #0xa5000014
        mov sa20, r12
        mov r12, #0xa5000018
        mov sa24, r12
        mov r20, #0xb5000020
        mov r21, #0xb5000021
        mov i0, r20
        mov i1, r21
        mov r4, #0x00000000
        and.testtanz.chan0 !c0, p0, r12, r12
        and.testtanz.chan0 !c0, p1, r4, r4
        and.testtanz.chan0 !c0, p2, r12, r12
        and.testtanz.chan0 !c0, p3, r4, r4
        br @done1
done1:
        mov r3, #0x00000002
        mov r6, #0x00000002
        stad [r1,+#1], r6                  ; cmd = 2: the next event reads
        idf drc0, bif
        wdf drc0
        stad [r1,+#2], r3                  ; state = done
        nop.end
done:
        mov r4, #0x00000000
        mov r3, #0x00000002
        ldad.bypassl1 r5, [r1,+#3], drc0   ; the run id, echoed
        wdf drc0
        stad [r1,+#5], r5
        stad [r1,+#1], r4                  ; cmd = 0
        idf drc0, bif
        wdf drc0
        stad [r1,+#2], r3                ; state = done
        br @tail
